insert into pricing_v2_preview_prices (pricing_id, model_internal_id, payload) values ('price:cohere/command-a-plus:standard:short:current', 'cohere/command-a-plus', '{"billingNote": "Cohere lists command-a-plus-05-2026 as Live and available through standard API endpoints, with no deprecation date. Its model page says both trial and production keys are free until rate limits are reached, while general pricing documentation says generative models including Command A+ are priced per token and the public pricing page says production keys are billed pay-as-you-go without publishing a Command A+ token rate. Standard Model Vault is a separate managed deployment option and lists Command A+ at $57.50 per XL instance-hour. V1 keeps Standard token, cached-input, and Batch prices null; null is not zero.", "calculationDefault": false, "charges": [], "contextClass": "short", "currency": "USD", "effectiveFrom": null, "effectiveUntil": null, "modelInternalId": "cohere/command-a-plus", "pricingId": "price:cohere/command-a-plus:standard:short:current", "processingMode": "standard", "promptTokenThreshold": null, "regionPolicy": "global", "sourceDatasetIds": {"publicDatasetIds": ["command-a-plus"], "websiteIds": []}, "sourceRefs": ["source:cohere:cohere-com-pricing", "source:cohere:docs-cohere-com-docs-command-a-plus", "source:cohere:docs-cohere-com-docs-deprecations", "source:cohere:docs-cohere-com-docs-how-does-cohere-pricing-work", "source:cohere:docs-cohere-com-docs-model-vault-standard-pricing", "source:cohere:docs-cohere-com-docs-models", "source:cohere:docs-cohere-com-docs-rate-limits", "source:cohere:docs-cohere-com-v2-changelog"], "verificationStatus": "partially_verified"}'::jsonb) on conflict (pricing_id) do update set model_internal_id = excluded.model_internal_id, payload = excluded.payload;
