insert into pricing_v2_preview_prices (pricing_id, model_internal_id, payload) values ('price:xai/grok-4.3:standard:short:current', 'xai/grok-4.3', '{"billingNote": "V1 pricing remains the short-context compatibility projection. Canonical Pricing V2 tiers model standard short-context prompt tokens < 200K and long-context prompt tokens >= 200K. Total prompt tokens include cached prompt tokens, and the selected tier applies to the whole request. Grok 4.3 Batch API pricing receives a 20% discount and is outside these standard tiers.", "calculationDefault": true, "charges": [{"amount": "1.25", "chargeId": "price:xai/grok-4.3:standard:short:current:input:text:per_1m_tokens", "component": "input", "modality": "text", "unit": "per_1m_tokens"}, {"amount": "0.2", "chargeId": "price:xai/grok-4.3:standard:short:current:cached_input:text:per_1m_tokens", "component": "cached_input", "modality": "text", "unit": "per_1m_tokens"}, {"amount": "2.5", "chargeId": "price:xai/grok-4.3:standard:short:current:output:text:per_1m_tokens", "component": "output", "modality": "text", "unit": "per_1m_tokens"}], "contextClass": "short", "currency": "USD", "effectiveFrom": null, "effectiveUntil": null, "modelInternalId": "xai/grok-4.3", "pricingId": "price:xai/grok-4.3:standard:short:current", "pricingStatus": "current", "processingMode": "standard", "promptTokenThreshold": 200000, "regionPolicy": "global", "sourceDatasetIds": {"publicDatasetIds": ["grok-4.3"], "websiteIds": []}, "sourceRefs": ["source:xai:docs-x-ai-developers-advanced-api-usage-prompt-caching-usage-and-pricing", "source:xai:docs-x-ai-developers-models-grok-4-3", "source:xai:docs-x-ai-developers-pricing", "source:xai:docs-x-ai-developers-rest-api-reference-inference-models"], "tierSelection": {"cachedPromptTokensIncluded": true, "comparison": "less_than", "tokenBasis": "total_prompt_tokens", "wholeRequestPricing": true}, "verificationStatus": "verified"}'::jsonb) on conflict (pricing_id) do update set model_internal_id = excluded